INSERT INTO product_translation (product_id, locale, name, description) VALUES (26, 'en', 'Coffee Mug - Express', 'Do you love mathematics? If so, then you need this elegant coffee mug with an amazing fractal design. You don''t have to worry about boring coffee mugs anymore. This coffee mug will be the topic of conversation in the office, guaranteed! Buy it now!');
INSERT INTO product_translation (product_id, locale, name, description) VALUES (26, 'pt', 'Caneca - Express', 'Adora matemática? Então precisa desta elegante caneca com um design fractal incrível. Chega de canecas aborrecidas — esta será o tema de conversa no escritório. Compre já!');
INSERT INTO product_translation (product_id, locale, name, description) VALUES (26, 'de', 'Kaffeebecher - Express', 'Lieben Sie Mathematik? Dann brauchen Sie diesen eleganten Kaffeebecher mit erstaunlichem Fraktaldesign. Keine langweiligen Becher mehr — dieses Stück wird im Büro zum Gesprächsthema. Jetzt kaufen!');
INSERT INTO product_translation (product_id, locale, name, description) VALUES (26, 'tr', 'Kahve Kupası - Express', 'Matematiği seviyor musunuz? O zaman bu zarif fraktal tasarımlı kahve kupasına ihtiyacınız var. Sıkıcı kupalarla uğraşmayın — bu kupa ofiste sohbet konusu olacak. Hemen alın!');
