INSERT INTO product_translation (product_id, locale, name, description) VALUES (51, 'en', 'Mouse Pad - Express', 'Fractal images are amazing! You can now own a mouse pad with a unique and amazing fractal. The mouse pad is made of a durable and smooth material. Your mouse will easily glide across the mouse pad. This mouse pad will brighten your workspace. Buy it now!');
INSERT INTO product_translation (product_id, locale, name, description) VALUES (51, 'pt', 'Tapete de Rato - Express', 'Imagens fractais são fantásticas! Possua um tapete de rato com um fractal único. Feito de material durável e suave para o rato deslizar facilmente. Ilumine o seu espaço de trabalho. Compre já!');
INSERT INTO product_translation (product_id, locale, name, description) VALUES (51, 'de', 'Mauspad - Express', 'Fraktalbilder sind fantastisch! Besitzen Sie ein Mauspad mit einem einzigartigen Fraktal. Aus langlebigem, glattem Material — Ihre Maus gleitet mühelos. Erhellen Sie Ihren Arbeitsplatz. Jetzt kaufen!');
INSERT INTO product_translation (product_id, locale, name, description) VALUES (51, 'tr', 'Mouse Pad - Express', 'Fraktal görseller harika! Benzersiz bir fraktallı mouse pad’e sahip olun. Dayanıklı ve pürüzsüz malzemeden üretilmiştir; fareniz kolayca kayar. Çalışma alanınızı aydınlatın. Hemen alın!');
