INSERT INTO product_translation (product_id, locale, name, description) VALUES (76, 'en', 'Luggage Tag - Cherish', 'This luggage tag will help you identify your luggage. The luggage tag is very unique and it will stand out from the crowd. The luggage tag is created out of a rugged and durable plastic. Buy this luggage tag now to make it easy to identify your luggage!');
INSERT INTO product_translation (product_id, locale, name, description) VALUES (76, 'pt', 'Etiqueta de Bagagem - Cherish', 'Esta etiqueta de bagagem ajuda a identificar a sua mala. É única e destaca-se. Feita de plástico resistente e durável. Compre já para identificar facilmente a sua bagagem!');
INSERT INTO product_translation (product_id, locale, name, description) VALUES (76, 'de', 'Kofferanhänger - Cherish', 'Dieses Kofferanhänger hilft Ihnen, Ihr Gepäck zu erkennen. Es ist einzigartig und fällt auf. Aus robustem, langlebigem Kunststoff. Kaufen Sie es jetzt, um Ihr Gepäck leicht zu finden!');
INSERT INTO product_translation (product_id, locale, name, description) VALUES (76, 'tr', 'Bavul Etiketi - Cherish', 'Bu bavul etiketi bagajınızı tanımanıza yardımcı olur. Çok özgün ve kalabalıktan ayrılır. Dayanıklı plastikten üretilmiştir. Bagajınızı kolayca tanımak için hemen alın!');
INSERT INTO product_translation (product_id, locale, name, description) VALUES (77, 'en', 'Luggage Tag - Adventure', 'This luggage tag will help you identify your luggage. The luggage tag is very unique and it will stand out from the crowd. The luggage tag is created out of a rugged and durable plastic. Buy this luggage tag now to make it easy to identify your luggage!');
